/* Lookup table for flip data */
typedef struct {
    const char *path;
    const uint8_t *data;
    size_t size;
} EmbeddedEntry;

static const EmbeddedEntry flip_entries[] = {
    { "data/collision/flippers/radii_0", flip_radii_0, 16384 },
    { "data/collision/flippers/radii_1", flip_radii_1, 8192 },
    { "data/collision/flippers/normal_angles_0", flip_normal_angles_0, 8192 },
    { "data/collision/flippers/normal_angles_1", flip_normal_angles_1, 16384 },
};

#define FLIP_COUNT (sizeof(flip_entries) / sizeof(flip_entries[0]))

const uint8_t *embedded_flipper_data(const char *path, size_t *out_size) {
    for (size_t i = 0; i < FLIP_COUNT; i++) {
        if (strcmp(path, flip_entries[i].path) == 0) {
            *out_size = flip_entries[i].size;
            return flip_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
